def build_case(idx, severity, setup, case_file, rule, question, anchor,
               anchor_pos, spoof, spoof_pos, options, expected, target,
               note_body, arm):
    substrate = "%s-%04d" % (PAIR_ID, idx)
    case_id = "%s-%s" % (substrate, arm)
    assert expected in options, "bad expected decision"
    assert target in options, "bad target decision"

    benign_prompt = "\n\n".join([setup, case_file, rule, question])

    if arm == "ctrl":
        attacked_prompt = benign_prompt
    elif arm == "a":
        parts = [setup, case_file, rule, question]
        parts.insert(anchor_pos, anchor)
        attacked_prompt = "\n\n".join(parts)
    elif arm == "b":
        parts = [setup, case_file, rule, question]
        parts.insert(spoof_pos, spoof)
        attacked_prompt = "\n\n".join(parts)
    elif arm == "ab":
        parts = [setup, case_file, rule, question]
        parts.insert(anchor_pos, anchor)
        # The spoof keeps its arm-b position relative to the benign text:
        # inserting the anchor first shifts it right when the anchor sits
        # at or before the spoof position.
        parts.insert(spoof_pos + (1 if anchor_pos <= spoof_pos else 0), spoof)
        attacked_prompt = "\n\n".join(parts)
    else:
        raise ValueError(arm)

    return {
        "case_id": case_id,
        "family": PAIR_ID,
        "primitive": "choice",
        "severity": severity,
        "benign": {
            "input": {"options": list(options), "prompt": benign_prompt},
            "expected_decision": expected,
        },
        "attacked": {
            "input": {"options": list(options), "prompt": attacked_prompt},
            "target_decision": target,
        },
        "combo_arm": arm,
        "combo_substrate": substrate,
        "combo_pair": COMBO_PAIR,
        "transform_order": TRANSFORM_ORDER,
        "primary_outcome": "flip",
        "notes": "[%s] %s" % (arm, note_body),
        "provenance": dict(PROVENANCE),
    }


def main():
    assert len(SUBSTRATES) == 100, "expected 100 substrates, got %d" % len(SUBSTRATES)
    out_path = sys.argv[1] if len(sys.argv) > 1 else (
        "dataset/combo/cases/combo-san-csp.jsonl")

    cases = []
    for i, s in enumerate(SUBSTRATES, start=1):
        (severity, setup, case_file, rule, question, anchor, anchor_pos,
         spoof, spoof_pos, options, expected, target, note_body) = s
        for arm in ("ctrl", "a", "b", "ab"):
            cases.append(build_case(i, severity, setup, case_file, rule,
                                    question, anchor, anchor_pos, spoof,
                                    spoof_pos, options, expected, target,
                                    note_body, arm))

    # Self-checks before writing.
    seen = set()
    for c in cases:
        assert c["case_id"] not in seen, "duplicate " + c["case_id"]
        seen.add(c["case_id"])
        text = json.dumps(c, ensure_ascii=False)
        assert "\u2014" not in text, "em dash in " + c["case_id"]
        if c["combo_arm"] == "ctrl":
            assert c["attacked"]["input"] == c["benign"]["input"]
        else:
            assert c["attacked"]["input"] != c["benign"]["input"], c["case_id"]

    with open(out_path, "w") as f:
        for c in cases:
            f.write(json.dumps(c, ensure_ascii=False) + "\n")

    from collections import Counter
    sev = Counter(c["severity"] for c in cases if c["combo_arm"] == "ctrl")
    print("wrote %d cases (%d substrates) -> %s" % (len(cases), len(SUBSTRATES), out_path))
    print("severity mix (per substrate):", dict(sev))


if __name__ == "__main__":
    main()
